{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
exposures = ['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
# within-farm correlation with yield
for e in exposures:
    cors=[]
    for f,g in df.groupby('farm'):
        cors.append(g[[e,'yield_kg']].dropna().corr().iloc[0,1])
    print(f"{e:16s} within-farm corr: {np.round(cors,3)} mean={np.mean(cors):.3f}")
"}
